//! The Diplomat Peak — Das letzte Kapitel.
//!
//! A first person horror walk through an abandoned mountain hotel in Baguio.
//! Everything below is procedural: there is not a single imported model or
//! image in this game that was not generated by the tools in `tools/`.

// A handful of helpers, markers and ambience categories are prepared for scenes
// that are not wired up yet (e.g. `props::railing`, `MenuAction::RestartFromEnd`).
// Keeping them silent makes the build output readable while the game grows.
#![allow(dead_code)]

mod audio;
mod collision;
mod core;
mod finale;
mod fx;
mod geom;
mod interact;
mod lighting;
mod palette;
mod player;
mod puzzles;
mod story;
mod ui;
mod world;

use bevy::prelude::*;
use bevy::window::WindowResolution;

use crate::audio::AudioPlugin;
use crate::core::{AppState, CorePlugin};
use crate::finale::FinalePlugin;
use crate::fx::FxPlugin;
use crate::interact::InteractPlugin;
use crate::lighting::LightingPlugin;
use crate::player::PlayerPlugin;
use crate::puzzles::PuzzlesPlugin;
use crate::story::StoryPlugin;
use crate::ui::UiPlugin;
use crate::world::WorldPlugin;

fn main() {
    App::new()
        .add_plugins(
            DefaultPlugins
                .set(WindowPlugin {
                    primary_window: Some(Window {
                        title: "The Diplomat Peak — Das letzte Kapitel".to_string(),
                        resolution: WindowResolution::new(1600.0, 900.0),
                        resizable: true,
                        ..default()
                    }),
                    ..default()
                })
                .set(ImagePlugin::default_linear()),
        )
        .init_state::<AppState>()
        .add_plugins((
            CorePlugin,
            AudioPlugin,
            PlayerPlugin,
            InteractPlugin,
            UiPlugin,
            WorldPlugin,
            LightingPlugin,
            FxPlugin,
            StoryPlugin,
            PuzzlesPlugin,
            FinalePlugin,
        ))
        .run();
}
